import java.util.Scanner;

public class Main {

    // 判断 n 的十进制数位长度是否等于 d
    public static boolean check(long n, int d, long[] p10) {
        return p10[d - 1] <= n && n < p10[d];
    }

    // 题面要求实现的功能写在外部函数里
    public static long solve(long x, long[] p10) {
        // 枚举可能的数位长度 d
        for (int d = 1; d <= 18; d++) {
            if (x % d != 0) {
                continue;
            }
            long n = x / d;
            if (n >= 1 && n <= 1_000_000_000_000_000_000L && check(n, d, p10)) {
                return n;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int T = sc.nextInt();

        // 预处理 10 的幂
        long[] p10 = new long[19];
        p10[0] = 1;
        for (int i = 1; i <= 18; i++) {
            p10[i] = p10[i - 1] * 10;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < T; i++) {
            long x = sc.nextLong();
            sb.append(solve(x, p10)).append('\n');
        }

        System.out.print(sb.toString());
        sc.close();
    }
}
